  bill: [ "UK Parliament: Terminally Ill Adults (End of Life) Bill", "https://bills.parliament.uk/publications/61635/documents/6735" ],
  notes: [ "House of Commons Library: Terminally Ill Adults bills", "https://commonslibrary.parliament.uk/terminally-ill-adults-end-of-life-bills/" ],
  impact: [ "UK Government: assisted-dying impact assessment", "https://www.gov.uk/government/publications/terminally-ill-adults-end-of-life-bill-impact-assessment" ],
  equality: [ "UK Government: assisted-dying equality impact assessment", "https://www.gov.uk/government/publications/terminally-ill-adults-end-of-life-bill-equality-impact-assessment/terminally-ill-adults-end-of-life-bill-equality-impact-assessment-html-version-as-introduced-to-the-lords" ],
  nhs: [ "NHS England: inequalities in palliative and end-of-life care", "https://www.england.nhs.uk/eolc/addressing-inequalities-in-palliative-and-end-of-life-care/" ],
  ons: [ "Office for National Statistics: suicide following severe health diagnoses", "https://www.ons.gov.uk/peoplepopulationandcommunity/birthsdeathsandmarriages/deaths/bulletins/suicidesamongpeoplediagnosedwithseverehealthconditionsengland/2017to2020" ],
